script:
frappe.ui.form.on('Property', {
    // Show/hide fields based on property type
    property_type: function(frm) {
        if (frm.doc.property_type === 'Commercial') {
            frm.toggle_display('avg_rent_sqft', true);
            frm.toggle_display('avg_rent_sqm', true);
        } else {
            frm.toggle_display('avg_rent_sqft', false);
            frm.toggle_display('avg_rent_sqm', false);
        }
    }
});

frappe.ui.form.on('Property Unit', {
    // Set property from parent if accessed from Property form
    setup: function(frm) {
        if (frm.doc.property) {
            // Get property owner
            frappe.db.get_value('Property', frm.doc.property, ['prop_owner', 'property_manager'])
            .then(r => {
                if (r.message) {
                    frm.set_value('unit_owner', r.message.prop_owner);
                    frm.set_value('property_manager', r.message.property_manager);
                }
            });
        }
    },

    // Calculate maintenance charge as % of rent
    rent_amount: function(frm) {
        if (frm.doc.rent_amount && !frm.doc.maintenance_charge) {
            // Default maintenance to 10% of rent
            var maintenance = frm.doc.rent_amount * 0.10;
            frm.set_value('maintenance_charge', maintenance);
        }
    }
});

frappe.ui.form.on('Lease Agreement', {
    refresh: function(frm) {
        // Show total lease duration
        if (frm.doc.start_date && frm.doc.end_date) {
            var start = new Date(frm.doc.start_date);
            var end = new Date(frm.doc.end_date);
            var diff_time = Math.abs(end - start);
            var diff_days = Math.ceil(diff_time / (1000 * 60 * 60 * 24));
            var months = Math.floor(diff_days / 30);
            frm.dashboard.set_indicator('Duration: ' + months + ' months', 'blue');
        }

        // Show rent collection stats
        if (frm.doc.total_rent_collected && frm.doc.rent_amount) {
            var expected = frm.doc.rent_amount * 12; // Assuming 1 year
            var collected = frm.doc.total_rent_collected;
            var percentage = (collected / expected * 100).toFixed(1);
            if (percentage >= 90) {
                frm.dashboard.set_indicator('Collection: ' + percentage + '%', 'green');
            } else if (percentage >= 70) {
                frm.dashboard.set_indicator('Collection: ' + percentage + '%', 'orange');
            } else {
                frm.dashboard.set_indicator('Collection: ' + percentage + '%', 'red');
            }
        }
    },

    // Auto-calculate end date from start date + duration
    start_date: function(frm) {
        if (frm.doc.start_date && !frm.doc.end_date) {
            // Default to 1 year lease
            var start = new Date(frm.doc.start_date);
            var end = new Date(start);
            end.setFullYear(end.getFullYear() + 1);
            frm.set_value('end_date', end.toISOString().split('T')[0]);
        }
    },

    // Set status based on dates
    validate: function(frm) {
        var today = new Date();
        var start_date = new Date(frm.doc.start_date);
        var end_date = new Date(frm.doc.end_date);

        if (end_date < today && frm.doc.status !== 'Cancelled') {
            frappe.msgprint("Warning: This lease has expired!");
        }

        if (frm.doc.rent_amount <= 0) {
            frappe.msgprint("Rent amount must be greater than 0");
            frappe.validated = false;
        }
    },

    // Update Property Unit status on save
    after_save: function(frm) {
        if (frm.doc.status === 'Active') {
            frappe.db.set_value('Property Unit', frm.doc.property_unit, {
                status: 'Occupied',
                current_tenant: frm.doc.tenant,
                current_lease: frm.doc.name
            });
        } else if (frm.doc.status === 'Cancelled' || frm.doc.status === 'Expired') {
            frappe.db.set_value('Property Unit', frm.doc.property_unit, {
                status: 'Available',
                current_tenant: '',
                current_lease: ''
            });
        }
    }
});

frappe.ui.form.on('Rentclear Customer', {
    refresh: function(frm) {
        // Show KYC status
        if (frm.doc.kyc_verified) {
            frm.dashboard.set_indicator('KYC Verified', 'green');
        } else {
            frm.dashboard.set_indicator('KYC Pending', 'orange');
        }

        // Show if customer is owner/tenant/both
        var roles = [];
        if (frm.doc.is_property_owner) roles.push('Owner');
        if (frm.doc.is_tenant) roles.push('Tenant');

        if (roles.length > 0) {
            frm.dashboard.set_comment('Role: ' + roles.join(' & '));
        }
    },

    // Validate required KYC fields based on customer type
    customer_type: function(frm) {
        if (frm.doc.customer_type === 'Individual') {
            frm.toggle_reqd(['aadhar_number', 'pan_number'], true);
        } else if (frm.doc.customer_type === 'Company') {
            frm.toggle_reqd(['company_pan_number', 'company_id_type', 'company_id_number', 'director_name'], true);
        }
    },

    // Validate Aadhar format
    aadhar_number: function(frm) {
        if (frm.doc.aadhar_number) {
            var aadhar = frm.doc.aadhar_number.replace(/\s/g, '');
            if (aadhar.length !== 12 || !/^\d+$/.test(aadhar)) {
                frappe.msgprint("Invalid Aadhar number! Must be 12 digits.");
                frm.set_value('aadhar_number', '');
            } else {
                frm.set_value('aadhar_number', aadhar.match(/.{1,4}/g).join(' '));
            }
        }
    },

    // Validate PAN format
    pan_number: function(frm) {
        if (frm.doc.pan_number) {
            var pan = frm.doc.pan_number.toUpperCase();
            if (!/^[A-Z]{5}[0-9]{4}[A-Z]{1}$/.test(pan)) {
                frappe.msgprint("Invalid PAN format! Example: ABCDE1234F");
            }
            frm.set_value('pan_number', pan);
        }
    }
});
